import{_ as t,o as e,c as _,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/93-判断对方的回应.md","filePath":"books/attached/93-判断对方的回应.md","lastUpdated":1794316978000}'),l={name:"books/attached/93-判断对方的回应.md"};function p(i,a,r,s,d,n){return e(),_("div",null,[...a[0]||(a[0]=[o('<h3 id="判断对方的回应" tabindex="-1">判断对方的回应 <a class="header-anchor" href="#判断对方的回应" aria-label="Permalink to &quot;判断对方的回应&quot;">​</a></h3><p>通过有效的沟通，你并不一定能一下子解决问题，或者马上弥合两人之间的差异。但是你可以通过对方的反应，第一时间判断出你的幸福于他而言，到底有多重要：</p><ul><li><p>对方是不是想搞清楚你的顾虑？</p></li><li><p>对方会不会立刻对你的问题做出回应？还是有刻意回避？</p></li><li><p>对方是否在认真考虑你的问题？或是就此问题来贬低你，让你觉得自己是个傻瓜？</p></li><li><p>对方是否会想个办法安抚你？还是急忙采取防御措施？</p></li><li><p>对方的回应是纯粹理性的吗？还是会站在你的角度来思考问题？</p></li></ul><p>如果你的伴侣对你的问题积极做出回应，并且会考虑到你的幸福与安全感，那你接下来的亲密关系多半畅通无阻。反之，你的伴侣要是一味逃避问题的关键，采取防御行为或是让你觉得自己又愚蠢又过分，那你就该对这段关系有所警觉了。</p>',4)])])}const m=t(l,[["render",p]]);export{h as __pageData,m as default};
